                className="w-full outline-none text-sm font-bold text-gray-900 bg-transparent placeholder:text-gray-200"
              />
            </div>
            <div className="flex flex-col border-l border-gray-50 pl-4">
              <span className="text-[10px] font-bold text-gray-400 uppercase mb-1">住院号</span>
              <input
                type="text"
                placeholder="ID号"
                value={patient.hospitalId}
                onChange={(e) => handleChange('hospitalId', e.target.value)}
                className="w-full outline-none text-sm font-bold text-gray-900 bg-transparent placeholder:text-gray-200"
              />
            </div>
          </div>

          {/* 性别与年龄 */}
          <div className="grid grid-cols-2 gap-4 py-3">
            <div className="flex flex-col">
              <span className="text-[10px] font-bold text-gray-400 uppercase mb-1">性别</span>
              <div className="flex bg-gray-100/50 p-1 rounded-xl w-fit">
                {['male', 'female'].map(g => (
                  <button
                    key={g}
                    onClick={() => handleChange('gender', g)}
                    className={`text-[10px] px-3 py-1 rounded-lg font-bold transition-all ${
                      patient.gender === g 
                        ? 'bg-white shadow-sm text-blue-600' 
                        : 'text-gray-400'
                    }`}
                  >
                    {g === 'male' ? '男' : '女'}
                  </button>
                ))}
              </div>
            </div>
            <div className="flex flex-col border-l border-gray-50 pl-4">
              <span className="text-[10px] font-bold text-gray-400 uppercase mb-1">年龄 (岁)</span>
              <input
                type="number"
                placeholder="0"
                value={patient.age}
                onChange={(e) => handleChange('age', e.target.value)}
                className="w-full outline-none text-sm font-bold text-gray-900 bg-transparent"
              />
            </div>
          </div>
        </div>
      </IOSCard>

      <IOSCard title="体格指标">
        <div className="space-y-4">
          <div className="flex items-center justify-between p-4 bg-gray-50/50 rounded-2xl">
            <div className="flex flex-col">
              <span className="text-[10px] font-bold text-gray-400 uppercase">Height</span>
              <div className="flex items-baseline">
                <input
                  type="number"
                  placeholder="0"
                  value={patient.height}
                  onChange={(e) => handleChange('height', e.target.value)}
                  className="w-16 bg-transparent outline-none text-xl font-black text-gray-900"
                />
                <span className="text-xs text-gray-400 ml-1">cm</span>
              </div>
            </div>
            <div className="w-[1px] h-8 bg-gray-200" />
            <div className="flex flex-col text-right">
              <span className="text-[10px] font-bold text-gray-400 uppercase">Weight</span>
              <div className="flex items-baseline justify-end">
                <input
                  type="number"
                  placeholder="0"
                  value={patient.weight}
                  onChange={(e) => handleChange('weight', e.target.value)}
                  className="w-16 bg-transparent outline-none text-xl font-black text-gray-900 text-right"
                />
                <span className="text-xs text-gray-400 ml-1">kg</span>
              </div>
            </div>
          </div>

          <div className="p-4 bg-blue-600 rounded-2xl flex items-center justify-between shadow-lg shadow-blue-200">
            <div className="flex items-center">
              <div className="p-2 bg-white/20 rounded-xl mr-3">
                <span className="text-white text-xs">📏</span>
              </div>
              <span className="text-sm font-bold text-white">体表面积 (BSA)</span>
            </div>
            <span className="text-lg font-black text-white">
              {bsa > 0 ? `${bsa.toFixed(2)}` : '--'} <span className="text-xs font-normal opacity-70">m²</span>
            </span>
          </div>
        </div>
      </IOSCard>

      <IOSCard title="实验室初诊数据">
        <div className="flex items-center justify-between p-2">
          <div className="flex flex-col">
            <span className="text-sm font-bold text-gray-700">初诊 WBC 计数</span>
            <span className="text-[10px] text-gray-400">×10⁹/L</span>
          </div>
          <input
            type="number"
            placeholder="0.0"
            value={patient.initialWbc}
            onChange={(e) => handleChange('initialWbc', e.target.value)}
            className="w-24 p-3 bg-gray-50 rounded-xl text-right outline-none text-lg font-black text-blue-600 focus:bg-blue-50 transition-colors"
          />
        </div>
      </IOSCard>
    </div>
  );
};

export default PatientInfoForm;

import React, { useState } from 'react';
import IOSCard from './IOSCard';

const MPALModule: React.FC = () => {
  const [markers, setMarkers] = useState<string[]>([]);

  const toggle = (m: string) => setMarkers(prev => 
    prev.includes(m) ? prev.filter(i => i !== m) : [...prev, m]
  );

  const diagnose = () => {
    const hasMyeloid = markers.includes('MPO') || (markers.includes('NSE') && markers.includes('CD11c'));
    const hasT = markers.includes('cCD3') || markers.includes('sCD3');
    const hasB = (markers.includes('CD19_strong') && (markers.includes('CD79a') || markers.includes('cCD22') || markers.includes('CD10'))) ||
                 (markers.includes('CD19_weak') && [markers.includes('CD79a'), markers.includes('cCD22'), markers.includes('CD10')].filter(Boolean).length >= 2);

    if (hasB && hasMyeloid) return 'MPAL (B/Myeloid)';
    if (hasT && hasMyeloid) return 'MPAL (T/Myeloid)';
    if (hasB && hasT) return 'MPAL (B/T)';
    return '不符合MPAL诊断标准';
  };

  const getButtonStyle = (m: string) => {
    return `transition-all duration-200 border rounded-xl p-3 text-xs font-semibold ${
      markers.includes(m) 
        ? 'bg-blue-50 border-blue-200 text-blue-700 shadow-sm shadow-blue-100' 
        : 'bg-white border-gray-100 text-gray-500 hover:border-gray-200'
    }`;
  };

  return (
    <div className="animate-in fade-in slide-in-from-bottom-4 duration-300">
      <IOSCard title="诊断结果">
        <div className="p-4 bg-blue-50/80 rounded-2xl text-center font-black text-blue-700 border border-blue-100/50">
          {diagnose()}
        </div>
      </IOSCard>

      <IOSCard title="髓系标记 (Myeloid)">
        <div className="space-y-3">
          <button 
            onClick={() => toggle('MPO')} 
            className={`w-full text-left ${getButtonStyle('MPO')}`}
          >
            <div className="flex justify-between items-center">
              <span>MPO 强表达 (&gt;3%)</span>
              {markers.includes('MPO') && <span className="text-[10px]">✅</span>}
            </div>
          </button>
          <div className="grid grid-cols-2 gap-2">
            {['NSE', 'CD11c', 'CD14', 'CD64'].map(m => (
              <button 
                key={m} 
                onClick={() => toggle(m)} 
                className={getButtonStyle(m)}
              >
                {m}
              </button>
            ))}
          </div>
        </div>
      </IOSCard>

      <IOSCard title="T系标记">
        <div className="grid grid-cols-2 gap-2">
          {['cCD3', 'sCD3'].map(m => (
            <button 
              key={m} 
              onClick={() => toggle(m)} 
              className={getButtonStyle(m)}
            >
              {m}
            </button>
          ))}
        </div>
      </IOSCard>

      <IOSCard title="B系标记">
        <div className="space-y-3">
          <div className="flex gap-2">
            <button 
              onClick={() => toggle('CD19_strong')} 
              className={`flex-1 ${getButtonStyle('CD19_strong')}`}
            >
              CD19 强表达
            </button>
            <button 
              onClick={() => toggle('CD19_weak')} 
              className={`flex-1 ${getButtonStyle('CD19_weak')}`}
            >
              CD19 弱表达
            </button>
          </div>
          <div className="grid grid-cols-3 gap-2">
            {['CD79a', 'cCD22', 'CD10'].map(m => (
              <button 
                key={m} 
                onClick={() => toggle(m)} 
                className={getButtonStyle(m)}
              >
                {m}
              </button>
            ))}
          </div>
        </div>
      </IOSCard>

      <div className="px-2 py-4">
        <p className="text-[9px] text-gray-400 leading-relaxed text-center italic">
          注：诊断标准参考 2016 WHO 分类。CD19 强/弱表达判定的判定需结合流式细胞术。
        </p>
      </div>
    </div>
  );
};

export default MPALModule;
